entries[459703] = { ["name"] = "Rückkopplung", ["text"] = "Sofort\nErhaltet die Fähigkeit 'Rückkopplung':\n\nIhr werdet 15 Sek. lang in ein Feld aus Antimagie gehüllt. Jeder erfolgreich auf den Priester gewirkte Zauber entzieht dem Angreifer 105 Mana. Für jeden auf diese Weise entzogenen Manapunkt erleidet das Ziel 1 Punkt Schattenschaden." }
