entries[461633] = { ["name"] = "Waffe des Frostbrands", ["text"] = "160 Mana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 187 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 25% zu verringern. Hält eine Stunde lang an." }
entries[461634] = { ["name"] = "Waffe der Flammenzunge", ["text"] = "155 Mana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Feuermagie. Jeder Treffer fügt 37 bis 112 zusätzlichen Feuerschaden zu, abhängig vom Waffentempo. Langsamere Waffen verursachen mehr Feuerschaden pro Schwung. Hält eine Stunde lang an." }
entries[461635] = { ["name"] = "Waffe des Felsbeißers", ["text"] = "150 Mana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen, erhöht die Nahkampfangriffskraft um 653 und ermöglicht es Nahkampfangriffen, bei Verwendung dieser Waffe zusätzliche Bedrohung zu erzeugen. Hält eine Stunde lang an." }
entries[461636] = { ["name"] = "Waffe des Windzorns", ["text"] = "165 Mana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Windmagie. Bei jedem Treffer besteht eine Chance von 20%, dass Ihr 2zusätzliche Angriffe mit 333 zusätzlicher Nahkampfangriffskraft erhaltet. Hält eine Stunde lang an." }
